from pydantic import BaseModel, Field

class Paper(BaseModel):
    """One provided paper: its own title and which of the OTHER provided papers it references."""
    title: str | None = Field(description="The title of this paper")
    cites_other_papers: list[str] = Field(
        description="Titles of OTHER provided papers that appear in this paper's bibliography"
    )

class Parse(BaseModel):
    papers: list[Paper]
